class InventoryGateway {                        // domain-facing contract
 public:
  explicit InventoryGateway(zmq::context_t& ctx)
      : socket_(ctx, zmq::socket_type::req) { socket_.connect("tcp://broker:5555"); }
  int checkStock(const std::string& sku) {      // a method call, not messaging
    socket_.send(zmq::buffer(sku), zmq::send_flags::none);
    zmq::message_t reply;
    socket_.recv(reply, zmq::recv_flags::none);
    return std::stoi(reply.to_string());
  }
 private: zmq::socket_t socket_;               // thread-affine, not shared
};
